int copy(const char *src, const char *dst) {
    int rc = -1;
    FILE *a = NULL, *b = NULL;
    char buf[8192];
    size_t n;

    if (!(a = fopen(src, "rb"))) goto done;
    if (!(b = fopen(dst, "wb"))) goto done;
    while ((n = fread(buf, 1, sizeof buf, a)) > 0)
        if (fwrite(buf, 1, n, b) != n) goto done;
    if (ferror(a)) goto done;
    rc = 0;
done:
    if (b && fclose(b) != 0) rc = -1;
    if (a) fclose(a);
    return rc;
}

